from collections import Counter

def components(grid, exclude=None):
    """4-connected same-color components, as (color, set of cells), skipping the given colors (e.g. background)."""
    H,W=len(grid),len(grid[0])
    skip={exclude} if exclude is not None else set()
    seen=set()
    for si in range(H):
        for sj in range(W):
            if grid[si][sj] in skip or (si,sj) in seen: continue
            c=grid[si][sj]; stack=[(si,sj)]; comp=set()
            while stack:
                p=stack.pop()
                if p in seen or grid[p[0]][p[1]]!=c: continue
                seen.add(p); comp.add(p); i,j=p
                for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
                    q=(i+di,j+dj)
                    if 0<=q[0]<H and 0<=q[1]<W: stack.append(q)
            yield c,comp

def bbox(comp):
    """(top, bottom, left, right) of a set of (i,j) cells."""
    rs=[i for i,_ in comp]; cs=[j for _,j in comp]
    return min(rs),max(rs),min(cs),max(cs)

def is_hollow_rect(comp):
    """True if the cells form a full rectangle outline."""
    t,b,l,r=bbox(comp); h,w=b-t+1,r-l+1
    return h>=2 and w>=2 and len(comp)==2*(h+w)-4

def background(grid):
    """The most common color in the grid."""
    return Counter(v for row in grid for v in row).most_common(1)[0][0]

